#!/bin/sh
# ==============================================================================
# SuperWiFi Self-Extracting OTA Update Script
# Version: 8.3.1
# ==============================================================================

set -e

echo "======================================================"
echo "    SuperWiFi Self-Extracting OTA Update (v8.3.1)"
echo "======================================================"

echo "[1/4] Stopping active SuperWiFi service..."
/etc/init.d/superwifi stop 2>/dev/null || true

echo "[2/4] Extracting update payload..."
TMP_DIR=$(mktemp -d /tmp/sw_ota_XXXXXX)
trap 'rm -rf "$TMP_DIR"' EXIT INT TERM

# Decode payload
sed '1,/^__PAYLOAD_BELOW__/d' "$0" | base64 -d | tar -xz -C "$TMP_DIR"

echo "[3/4] Copying files to system..."
# Preserve /etc/config/superwifi
cp -rf "$TMP_DIR/usr/"* /usr/ 2>/dev/null || true
cp -rf "$TMP_DIR/www/"* /www/ 2>/dev/null || true
cp -rf "$TMP_DIR/etc/init.d/"* /etc/init.d/ 2>/dev/null || true
cp -f "$TMP_DIR/etc/superwifi/schema.sql" /etc/superwifi/schema.sql 2>/dev/null || true
cp -f "$TMP_DIR/etc/superwifi-version" /etc/superwifi-version 2>/dev/null || true

# Set permissions
chmod +x /usr/lib/superwifi/*.sh 2>/dev/null || true
chmod +x /usr/sbin/sw* 2>/dev/null || true
chmod +x /www/cgi-bin/*.sh /www/index.cgi 2>/dev/null || true
chmod +x /etc/init.d/superwifi 2>/dev/null || true

echo "[4/4] Updating database schema, applying patches & repairing sessions..."
DB_PATH=$(uci get superwifi.core.db_path 2>/dev/null || echo "/etc/superwifi/superwifi.db")
if [ -f "$DB_PATH" ] && [ -f "/etc/superwifi/schema.sql" ]; then
    sqlite3 "$DB_PATH" < /etc/superwifi/schema.sql 2>/dev/null || true
fi

# Run session repair & patch execution during OTA update
/usr/sbin/sw repair 2>/dev/null || {
    [ -f /usr/lib/superwifi/sw-patches.sh ] && sh /usr/lib/superwifi/sw-patches.sh 2>/dev/null || true
}

/etc/init.d/superwifi enable 2>/dev/null || true
/etc/init.d/superwifi restart 2>/dev/null || true

echo "======================================================"
echo " 🎉 OTA Update to v8.3.1 completed successfully!"
echo "======================================================"
exit 0

__PAYLOAD_BELOW__

